/* Rentcam CMS product sync v10 */
(function(){
  if(!location.pathname.startsWith('/cms')) return;
  const publishing=()=>window.RentcamCmsPublishing;
  const cfg=()=>publishing().get();
  const custom=id=>(cfg()?.customProducts||[]).find(x=>String(x.id)===String(id));
  const ov=id=>(cfg()?.productOverrides||{})[id]||{};
  const isActive=id=>publishing().isProductActive(id);
  function clickSave(){return publishing().save().catch(e=>console.error('Gagal menyimpan produk CMS',e))}
  function refreshProducts(){setTimeout(()=>document.querySelector('[data-nav="products"]')?.click(),450)}
  function toast(text){const x=document.createElement('div');x.textContent=text;x.style.cssText='position:fixed;right:18px;top:86px;z-index:100000;background:#17181a;color:#fff;padding:11px 14px;border-radius:10px;font:700 13px system-ui;box-shadow:0 10px 30px rgba(0,0,0,.18)';document.body.appendChild(x);setTimeout(()=>x.remove(),1800)}
  function ensureStyle(){if(document.getElementById('rcps10-style'))return;const s=document.createElement('style');s.id='rcps10-style';s.textContent='.rcps10-actions{display:flex;gap:7px;align-items:center;white-space:nowrap}.rcps10-delete{color:#c62828!important;background:#fff3f3!important;border-color:#ffd0d0!important}.rcps10-modal{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.48);display:grid;place-items:center;padding:18px}.rcps10-box{width:min(440px,100%);background:#fff;border-radius:16px;padding:20px;box-shadow:0 24px 70px rgba(0,0,0,.25)}.rcps10-box h3{margin:0 0 8px}.rcps10-name{display:block;margin:12px 0;padding:10px 12px;background:#f5f6f7;border-radius:10px;font-weight:800}.rcps10-foot{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.rcps10-foot button{height:40px;padding:0 15px;border-radius:9px;border:1px solid #ddd;background:#fff;font-weight:800}.rcps10-foot .danger{background:#d92d20;color:#fff;border-color:#d92d20}';document.head.appendChild(s)}
  function patchRows(){ensureStyle();document.querySelectorAll('button[data-act="edit-product"][data-id]').forEach(edit=>{const td=edit.closest('td');if(!td||td.querySelector('.rcps10-actions'))return;const id=edit.dataset.id;const wrap=document.createElement('div');wrap.className='rcps10-actions';const toggle=document.createElement('button');toggle.className='v5-btn';toggle.dataset.rcps10Toggle=id;toggle.textContent=isActive(id)?'Nonaktif':'Aktifkan';const del=document.createElement('button');del.className='v5-btn rcps10-delete';del.dataset.rcps10Delete=id;del.textContent='Hapus';td.insertBefore(wrap,edit);wrap.append(toggle,edit,del)})}
  function toggleProduct(id){const next=!isActive(id);publishing().setProductActive(id,next);clickSave();refreshProducts();toast(next?'Produk diaktifkan.':'Produk dinonaktifkan.')}
  function deleteProduct(id,row){const x=custom(id),name=row?.querySelector('.v5-prod b')?.textContent||id;const m=document.createElement('div');m.className='rcps10-modal';m.innerHTML='<div class="rcps10-box"><h3>Hapus Produk</h3><p>Yakin ingin menghapus produk ini?</p><span class="rcps10-name"></span><p style="font-size:12px;color:#666">'+(x?'Produk custom akan dihapus permanen.':'Produk bawaan akan dinonaktifkan dan ditandai terhapus sehingga bisa dipulihkan.')+'</p><div class="rcps10-foot"><button data-cancel>Batal</button><button class="danger" data-confirm>Hapus</button></div></div>';m.querySelector('.rcps10-name').textContent=name;m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-cancel]'))m.remove();if(e.target.closest('[data-confirm]')){publishing().deleteProduct(id);m.remove();clickSave();refreshProducts();toast('Produk berhasil dihapus.')}});document.body.appendChild(m)}
  document.addEventListener('click',e=>{const saveModal=e.target.closest('[data-act="save-modal"]');if(saveModal)setTimeout(clickSave,60);const t=e.target.closest('[data-rcps10-toggle]');if(t){e.preventDefault();e.stopPropagation();toggleProduct(t.dataset.rcps10Toggle)}const d=e.target.closest('[data-rcps10-delete]');if(d){e.preventDefault();e.stopPropagation();deleteProduct(d.dataset.rcps10Delete,d.closest('tr'))}},false);
  setInterval(patchRows,400);setTimeout(patchRows,200);
})();